import 'package:flutter/material.dart';

import 'palette.dart';

/// Brandhoop's colours, taken from the logo: a deep navy, a slate grey for the
/// phone body, a burnt orange accent, and a clean off-white.
/// Brandhoop's colours, taken from the logo: a deep navy, a slate grey for the
/// phone body, a burnt orange accent, and a clean off-white. The full ramps live in
/// palette.dart (generated by tools/brand/palette.py); these are the names the
/// screens already use.
class BrandColors {
  const BrandColors._();

  static const Color indigo = Palette.navy700;
  static const Color indigoDeep = Palette.navy800;
  static const Color navy2 = Palette.navy600;
  static const Color slate = Palette.slate600;
  static const Color saffron = Palette.saffron500;
  static const Color saffronSoft = Palette.saffron100;
  static const Color green = Palette.green;
  static const Color red = Palette.red;
  static const Color paper = Palette.slate50;
}

ThemeData buildTheme(Brightness brightness) {
  final bool dark = brightness == Brightness.dark;
  final ColorScheme scheme = ColorScheme.fromSeed(
    seedColor: BrandColors.indigo,
    brightness: brightness,
    secondary: BrandColors.saffron,
  );
  final Color bg = dark ? Palette.nightBg : Palette.lightBg;
  final RoundedRectangleBorder shape12 =
      RoundedRectangleBorder(borderRadius: BorderRadius.circular(14));
  return ThemeData(
    useMaterial3: true,
    colorScheme: scheme,
    scaffoldBackgroundColor: bg,
    visualDensity: VisualDensity.standard,
    appBarTheme: AppBarTheme(
      backgroundColor: bg,
      surfaceTintColor: Colors.transparent,
      elevation: 0,
      scrolledUnderElevation: 0.5,
      centerTitle: false,
      titleTextStyle: TextStyle(
        color: scheme.onSurface,
        fontSize: 20,
        fontWeight: FontWeight.w700,
      ),
    ),
    cardTheme: CardThemeData(
      elevation: 0,
      margin: EdgeInsets.zero,
      color: dark ? Palette.nightSurface : Palette.lightSurface,
      surfaceTintColor: Colors.transparent,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(20),
        side: BorderSide(color: dark ? Palette.nightLine : Palette.lightLine),
      ),
    ),
    inputDecorationTheme: InputDecorationTheme(
      filled: true,
      fillColor: dark ? Palette.nightSurface : Palette.lightSurface,
      border: OutlineInputBorder(
        borderRadius: BorderRadius.circular(12),
        borderSide: BorderSide(color: scheme.outlineVariant),
      ),
      enabledBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(12),
        borderSide: BorderSide(color: scheme.outlineVariant),
      ),
      focusedBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(12),
        borderSide: BorderSide(color: scheme.primary, width: 1.6),
      ),
      contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 14),
    ),
    filledButtonTheme: FilledButtonThemeData(
      style: FilledButton.styleFrom(
        minimumSize: const Size(64, 50),
        shape: shape12,
        textStyle: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700),
      ),
    ),
    outlinedButtonTheme: OutlinedButtonThemeData(
      style: OutlinedButton.styleFrom(
        minimumSize: const Size(64, 50),
        shape: shape12,
        textStyle: const TextStyle(fontSize: 15, fontWeight: FontWeight.w600),
      ),
    ),
    textButtonTheme: TextButtonThemeData(
      style: TextButton.styleFrom(
        shape: shape12,
        textStyle: const TextStyle(fontWeight: FontWeight.w600),
      ),
    ),
    chipTheme: ChipThemeData(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      side: BorderSide(color: scheme.outlineVariant),
      labelStyle: TextStyle(fontWeight: FontWeight.w600, color: scheme.onSurface),
    ),
    navigationBarTheme: NavigationBarThemeData(
      height: 68,
      backgroundColor: dark ? Palette.nightSurface : Palette.lightSurface,
      surfaceTintColor: Colors.transparent,
      indicatorColor: dark ? Palette.saffron500.withValues(alpha: 0.28) : Palette.saffron100,
      iconTheme: WidgetStateProperty.resolveWith<IconThemeData>((Set<WidgetState> st) => IconThemeData(
            color: st.contains(WidgetState.selected) ? (dark ? Palette.saffron300 : Palette.navy700) : (dark ? Palette.slate400 : Palette.slate600),
          )),
      labelTextStyle: WidgetStateProperty.resolveWith<TextStyle>((Set<WidgetState> st) => TextStyle(
            fontSize: 12,
            fontWeight: st.contains(WidgetState.selected) ? FontWeight.w800 : FontWeight.w600,
            color: st.contains(WidgetState.selected) ? (dark ? Palette.saffron300 : Palette.navy700) : (dark ? Palette.slate400 : Palette.slate600),
          )),
    ),
    dividerTheme: DividerThemeData(
      color: scheme.outlineVariant.withValues(alpha: 0.6),
      space: 1,
      thickness: 1,
    ),
    snackBarTheme: SnackBarThemeData(
      behavior: SnackBarBehavior.floating,
      shape: shape12,
    ),
    dialogTheme: DialogThemeData(shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20))),
    bottomSheetTheme: const BottomSheetThemeData(
      showDragHandle: true,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
    ),
    listTileTheme: const ListTileThemeData(contentPadding: EdgeInsets.symmetric(horizontal: 16)),
  );
}
